    git restore --source=HEAD -- $dockTest
    if ($LASTEXITCODE -ne 0) { throw "Failed to remove the accidental out-of-scope dock test change" }
}

$protected = git diff --name-only | Where-Object { $_ -match "AppRoot.kt|TodayScreen.kt|SettingsScreen.kt|HeartRate" }
if ($protected) { throw "Protected UI changed: $($protected -join ", ")" }
git diff --check
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed" }
Write-Host "FINAL current-source patch applied." -ForegroundColor Green
Write-Host "Dock implementation/settings, Home, Today HR, backup and archive were not changed." -ForegroundColor Cyan
